let activeId='normal',view='chat',variant=new URLSearchParams(location.search).get('variant')||'A',selection=null,openTurns=new Set(),openRequests=new Set(),drafts={},busyId=null,stopping=false,query='',scope='all',wrap=true,jsonOpen=new Set(),dialogAction=null,pendingTimer=null,hasNew=false;
