function switchVariant(delta){variant=['A','B','C'][(['A','B','C'].indexOf(variant)+delta+3)%3];const url=new URL(location.href);url.searchParams.set('variant',variant);history.replaceState({},'',url);jsonOpen.clear();renderShell();}
function finish(stopped=false){if(!busyId)return;const s=sessions.find(x=>x.id===busyId),t=s.turns.at(-1),e=t.events.at(-1);e.state='completed';e.duration=950;e.call=828;e.output={is_error:false,content:[{type:'text',text:'当前工具真实模拟返回已保存。'}]};e.backfill={type:'tool_result',tool_use_id:`toolu-${t.id}-2`,content:JSON.stringify(e.output),is_error:false};t.state=stopped?'terminated':'completed';t.mode=stopped?'stopped':'normal';t.reason=stopped?'用户停止':null;t.duration=2860;
  if(stopped){t.source='application';t.answer='本轮已在当前调用返回后停止，已取得的模拟结果保留；没有发起后续模型请求。此说明由应用生成。';}else{t.source='model';t.answer='模拟查询已完成。已取得两处地点结果，交通、门票与营业时间仍待核实。';const r={id:`${t.id}-r2`,type:'model',name:'模型请求 2',state:'completed',at:2.86,duration:1600,input:{...structuredClone(t.requests[0].input),messages:[...t.requests[0].input.messages,{role:'assistant',content:t.requests[0].output.content},{role:'user',content:t.requests[0].children.map(c=>c.backfill)}]},output:{content:[{type:'text',text:t.answer}],stop_reason:'end_turn',usage:{input_tokens:1520,output_tokens:340}},usage:{input_tokens:1520,output_tokens:340},children:[]};t.requests.push(r);t.events.push(r);t.duration=4460;openRequests.add(r.id);}
  busyId=null;stopping=false;s.time='刚刚 · 模拟保存';if(activeId===s.id){renderShell();if(view==='chat')$('#messages').scrollTop=$('#messages').scrollHeight;else if($('#follow').checked)selectEvent(t.events.at(-1).id);else{hasNew=true;$('#trace-body').insertAdjacentHTML('afterbegin','<button class="jump-latest" data-action="latest">有新事件 · 跳到最新</button>');}}else renderShell();}
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.session){activeId=b.dataset.session;if(activeId==='running'&&current().turns.at(-1).state==='running')busyId='running';initExpansion();renderShell();return;}if(b.dataset.tab){view=b.dataset.tab;renderShell();return;}if(b.dataset.traceTurn){view='trace';renderShell();selectEvent(b.dataset.traceTurn);return;}if(b.dataset.turn){const id=b.dataset.turn;openTurns.has(id)?openTurns.delete(id):openTurns.add(id);renderTrace();return;}if(b.dataset.request){const id=b.dataset.request;openRequests.has(id)?openRequests.delete(id):openRequests.add(id);renderTrace();return;}if(b.dataset.event){selectEvent(b.dataset.event);return;}if(b.dataset.locateTurn){openTurns.add(b.dataset.locateTurn);renderTrace();document.getElementById(`card-${b.dataset.locateTurn}`)?.scrollIntoView({block:'start'});return;}if(b.dataset.hit){selectEvent(b.dataset.hit,b.dataset.section||null);return;}if(b.dataset.copy){const e=allEvents().find(x=>x.id===selection),p=sections(e).find(p=>p.key===b.dataset.copy);try{await navigator.clipboard.writeText(typeof p.data==='string'?p.data:JSON.stringify(p.data,null,2));b.textContent='已复制';}catch{b.textContent='请在下方选择文本复制';}return;}
  switch(b.dataset.action){case 'new':activeId='draft';view='chat';initExpansion();renderShell();break;case 'prev':switchVariant(-1);break;case 'next':switchVariant(1);break;case 'expand':current()?.turns.forEach(t=>{openTurns.add(t.id);t.requests.forEach(r=>openRequests.add(r.id));});renderTrace();break;case 'collapse':openTurns.clear();openRequests.clear();selection=null;jsonOpen.clear();renderTrace();break;case 'close-detail':selection=null;renderTrace();break;case 'wrap':wrap=!wrap;renderTrace();break;case 'finish':finish();break;case 'stop':stopping=true;renderShell();pendingTimer=setTimeout(()=>finish(true),1800);break;case 'latest':hasNew=false;selectEvent(current().turns.at(-1).events.at(-1).id);break;case 'rename':case 'delete':if(!current())return;dialogAction=b.dataset.action;$('#dialog-title').textContent=dialogAction==='rename'?'重命名助手会话':'删除这个模拟会话？';$('#dialog-description').textContent=dialogAction==='rename'?'标题仅用于展示，不改变上下文。':'会话及其执行轨迹将从本次原型内存中删除。刷新页面可恢复所有样例。';$('#rename-label').hidden=dialogAction!=='rename';$('#rename-input').value=current().title;$('#manage').showModal();break;}
});
$('#manage').addEventListener('close',()=>{if($('#manage').returnValue!=='confirm')return;if(dialogAction==='rename'&&$('#rename-input').value.trim())current().title=$('#rename-input').value.trim();if(dialogAction==='delete'&&activeId!==busyId){sessions=sessions.filter(s=>s.id!==activeId);activeId='draft';initExpansion();}renderShell();});
$('#draft').addEventListener('input',ev=>drafts[activeId]=ev.target.value);
$('#composer').addEventListener('submit',ev=>{ev.preventDefault();const text=$('#draft').value.trim();if(!text||busyId)return;if(!current()){const id=`session-${++serial}`;sessions.unshift({id,title:text.slice(0,22),time:'刚刚 · 模拟保存',turns:[]});activeId=id;}const t=makeTurn(text,'running');const previous=current().turns.filter(x=>x.mode!=='interrupted').flatMap(x=>[{role:'user',content:x.input},{role:'assistant',content:x.answer}]);t.requests[0].input.messages=[...previous,{role:'user',content:text}];current().turns.push(t);drafts[activeId]='';drafts.draft='';busyId=activeId;stopping=false;openTurns.add(t.id);openRequests.add(t.requests[0].id);renderShell();$('#messages').scrollTop=$('#messages').scrollHeight;});
$('#draft').addEventListener('keydown',ev=>{if(ev.key==='Enter'&&!ev.shiftKey&&!ev.isComposing){ev.preventDefault();$('#composer').requestSubmit();}});
$('#search').addEventListener('input',ev=>{query=ev.target.value;renderTrace();});$('#scope').addEventListener('change',ev=>{scope=ev.target.value;renderTrace();});
$('#follow').addEventListener('change',()=>{if($('#follow').checked&&hasNew){hasNew=false;selectEvent(current().turns.at(-1).events.at(-1).id);}});
document.addEventListener('keydown',ev=>{if(ev.target.matches('input,textarea,select,[contenteditable]')||$('#manage').open)return;if(ev.key==='ArrowLeft'||ev.key==='ArrowRight'){ev.preventDefault();switchVariant(ev.key==='ArrowRight'?1:-1);}if(ev.key==='Escape'&&selection){selection=null;renderTrace();}});
renderShell();
